CREATE TABLE "team_championship" (
	"team_id" integer NOT NULL,
	"championship" text NOT NULL,
	CONSTRAINT "team_championship_team_id_championship_pk" PRIMARY KEY("team_id","championship")
);
--> statement-breakpoint
-- Backfill di sicurezza: ogni squadra esistente nasce nei regolari.
-- Lo script sql/historical_data.sql corregge poi le OIS 11-17 (biennio/esordienti
-- e le 'bt-', iscritte a entrambi i campionati). Senza questo INSERT le edizioni
-- fuori da quelle liste (es. OIS 6-10) resterebbero senza appartenenza e
-- sparirebbero da tutte le classifiche.
INSERT INTO "team_championship" ("team_id", "championship") SELECT "id", 'regolari' FROM "team";
