CREATE MATERIALIZED VIEW "public"."v00a_task_stats" AS (select "team_task_score"."task_id", "team_championship"."championship" as "championship", count(distinct "team_task_score"."team_id") as "team_scored", ROUND(COALESCE(sum("team_task_score"."score"), 0)::numeric, 2)::float8 as "total_scores", ROUND(COALESCE(max("team_task_score"."score"), 0)::numeric, 2)::float8 as "max_score", ROUND(COALESCE(avg("team_task_score"."score"), 0)::numeric, 2)::float8 as "avg_score", ROUND(COALESCE(ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY "team_task_score"."score")::numeric, 2)::float8, 0)::numeric, 2)::float8 as "median_score" from "team_task_score" inner join "team" on ("team"."id" = "team_task_score"."team_id" and "team"."hidden" = false) inner join "team_championship" on "team_championship"."team_id" = "team"."id" inner join "task" on "task"."id" = "team_task_score"."task_id" inner join "round" on ("round"."id" = "task"."round_id" and "round"."public" = true) inner join "edition" on ("edition"."id" = "round"."edition_id" and "edition"."public" = true) where ("team_task_score"."score" > '0' and ("team_championship"."championship" = 'regolari' OR "round"."slug" <> 'final') and not exists (select "penalized_team_round"."id" from "team_round" "penalized_team_round" inner join "team_round_penalization" on "team_round_penalization"."team_round_id" = "penalized_team_round"."id" inner join "penalization" on "penalization"."id" = "team_round_penalization"."penalization_id" where ("penalized_team_round"."team_id" = "team"."id" and "penalization"."level" = 'red' and "penalization"."sent_at" is not null and ("penalization"."appeal_approved" is null or "penalization"."appeal_approved" = false)))) group by "team_task_score"."task_id", "team_championship"."championship");--> statement-breakpoint
CREATE MATERIALIZED VIEW "public"."v01a_team_task_score_stats" AS (select "team_task_score"."id", "team_championship"."championship" as "championship", (RANK() OVER (
          PARTITION BY "team_task_score"."task_id", "team_championship"."championship"
          ORDER BY "team_task_score"."score" DESC
        ))::int as "rank_tot" from "team_task_score" inner join "team" on ("team"."id" = "team_task_score"."team_id" and "team"."hidden" = false) inner join "team_championship" on "team_championship"."team_id" = "team"."id" inner join "task" on "task"."id" = "team_task_score"."task_id" inner join "round" on ("round"."id" = "task"."round_id" and "round"."public" = true) inner join "edition" on ("edition"."id" = "round"."edition_id" and "edition"."public" = true) where (("team_championship"."championship" = 'regolari' OR "round"."slug" <> 'final') and not exists (select "penalized_team_round"."id" from "team_round" "penalized_team_round" inner join "team_round_penalization" on "team_round_penalization"."team_round_id" = "penalized_team_round"."id" inner join "penalization" on "penalization"."id" = "team_round_penalization"."penalization_id" where ("penalized_team_round"."team_id" = "team"."id" and "penalization"."level" = 'red' and "penalization"."sent_at" is not null and ("penalization"."appeal_approved" is null or "penalization"."appeal_approved" = false)))));--> statement-breakpoint
CREATE MATERIALIZED VIEW "public"."v02b_team_round_stats" AS (select "team_round"."id", "team_championship"."championship" as "championship", ROUND(COALESCE(sum("team_task_score"."score"), 0)::numeric, 2)::float8 as "total_scores", (RANK() OVER (
          PARTITION BY "team_round"."round_id", "team_championship"."championship"
          ORDER BY ROUND(COALESCE(sum("team_task_score"."score"), 0)::numeric, 2)::float8 DESC
        ))::int as "rank_tot", (RANK() OVER (
          PARTITION BY "team_round"."round_id", "team_championship"."championship", "institute"."region"
          ORDER BY ROUND(COALESCE(sum("team_task_score"."score"), 0)::numeric, 2)::float8 DESC
        ))::int as "rank_reg", CASE
                                  WHEN "team_championship"."championship" <> 'regolari' THEN null
                                  WHEN PERCENT_RANK() OVER (PARTITION BY "team_round"."round_id", "team_championship"."championship" ORDER BY ROUND(COALESCE(sum("team_task_score"."score"), 0)::numeric, 2)::float8 DESC) = 0    THEN 0
                                  WHEN PERCENT_RANK() OVER (PARTITION BY "team_round"."round_id", "team_championship"."championship" ORDER BY ROUND(COALESCE(sum("team_task_score"."score"), 0)::numeric, 2)::float8 DESC) <= 0.05 THEN 1
                                  WHEN PERCENT_RANK() OVER (PARTITION BY "team_round"."round_id", "team_championship"."championship" ORDER BY ROUND(COALESCE(sum("team_task_score"."score"), 0)::numeric, 2)::float8 DESC) <= 0.15 THEN 2
                                  WHEN PERCENT_RANK() OVER (PARTITION BY "team_round"."round_id", "team_championship"."championship" ORDER BY ROUND(COALESCE(sum("team_task_score"."score"), 0)::numeric, 2)::float8 DESC) <= 0.30 THEN 3
                                  ELSE null
                                END as "medal" from "team" inner join "team_championship" on "team_championship"."team_id" = "team"."id" inner join "edition" on ("edition"."id" = "team"."edition_id" and "edition"."public" = true) inner join "round" on ("round"."edition_id" = "edition"."id" and "round"."public" = true and (("team_championship"."championship" = 'regolari' AND "team"."finalist" = true) OR "round"."slug" <> 'final')) left join "team_round" on ("team_round"."team_id" = "team"."id" and "team_round"."round_id" = "round"."id") left join "task" on "task"."round_id" = "round"."id" left join "team_task_score" on ("team_task_score"."team_id" = "team"."id" and "team_task_score"."task_id" = "task"."id") inner join "institute" on "institute"."id" = "team"."inst_id" where ("team"."hidden" = false and exists (
  select 1
  from team_task_score s
  join task t on t.id = s.task_id
  join team tm on tm.id = s.team_id
  join team_championship tc on tc.team_id = tm.id
  where t.round_id = "round"."id"
    and tc.championship = "team_championship"."championship"
    and tm.hidden = false
) and not exists (select "team_round_penalization"."id" from "team_round_penalization" inner join "penalization" on "penalization"."id" = "team_round_penalization"."penalization_id" where ("team_round_penalization"."team_round_id" = "team_round"."id" and "penalization"."level" = 'yellow' and "penalization"."sent_at" is not null and ("penalization"."appeal_approved" is null or "penalization"."appeal_approved" = false))) and not exists (select "penalized_team_round"."id" from "team_round" "penalized_team_round" inner join "team_round_penalization" on "team_round_penalization"."team_round_id" = "penalized_team_round"."id" inner join "penalization" on "penalization"."id" = "team_round_penalization"."penalization_id" where ("penalized_team_round"."team_id" = "team"."id" and "penalization"."level" = 'red' and "penalization"."sent_at" is not null and ("penalization"."appeal_approved" is null or "penalization"."appeal_approved" = false)))) group by "team_round"."id", "team_championship"."championship", "institute"."region");--> statement-breakpoint
CREATE MATERIALIZED VIEW "public"."v03b_round_stats" AS (select "round"."id", v02b_team_round_stats.championship as "championship", count(distinct "team_round"."team_id") as "team_scored", ROUND(COALESCE(sum("total_scores"), 0)::numeric, 2)::float8 as "total_scores", ROUND(COALESCE(max("total_scores"), 0)::numeric, 2)::float8 as "max_score", ROUND(COALESCE(avg("total_scores"), 0)::numeric, 2)::float8 as "avg_score", ROUND(COALESCE(ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY "total_scores")::numeric, 2)::float8, 0)::numeric, 2)::float8 as "median_score" from "round" inner join "team_round" on "team_round"."round_id" = "round"."id" inner join "v02b_team_round_stats" on "v02b_team_round_stats"."id" = "team_round"."id" inner join "edition" on ("edition"."id" = "round"."edition_id" and "edition"."public" = true) where ("round"."public" = true and "total_scores" > 0) group by "round"."id", v02b_team_round_stats.championship);--> statement-breakpoint
CREATE MATERIALIZED VIEW "public"."v04a_team_stats" AS (select "team"."id", "team_championship"."championship" as "championship", ROUND(COALESCE(sum("total_scores"), 0)::numeric, 2)::float8 as "total_scores", (RANK() OVER (
          PARTITION BY "team"."edition_id", "team_championship"."championship"
          ORDER BY ROUND(COALESCE(sum("total_scores"), 0)::numeric, 2)::float8 DESC
        ))::int as "rank_tot", (RANK() OVER (
          PARTITION BY "team"."edition_id", "team_championship"."championship", "institute"."region"
          ORDER BY ROUND(COALESCE(sum("total_scores"), 0)::numeric, 2)::float8 DESC
        ))::int as "rank_reg", ROUND(COALESCE(avg("rank_tot"), 0)::numeric, 2)::float8 as "avg_round_rank", ROUND(COALESCE(min("rank_tot"), 0)::numeric, 2)::float8 as "best_round_rank", JSON_BUILD_OBJECT(
        0, COUNT(*) FILTER (WHERE "medal" = 0),
        1, COUNT(*) FILTER (WHERE "medal" = 1),
        2, COUNT(*) FILTER (WHERE "medal" = 2),
        3, COUNT(*) FILTER (WHERE "medal" = 3)
      ) as "total_medals" from "team" inner join "team_championship" on "team_championship"."team_id" = "team"."id" inner join "edition" on ("edition"."id" = "team"."edition_id" and "edition"."public" = true) inner join "round" on ("round"."edition_id" = "edition"."id" and "round"."public" = true and (("team_championship"."championship" = 'regolari' AND "team"."finalist" = true) OR "round"."slug" <> 'final')) left join "team_round" on ("team_round"."team_id" = "team"."id" and "team_round"."round_id" = "round"."id") left join "v02b_team_round_stats" on ("v02b_team_round_stats"."id" = "team_round"."id" and v02b_team_round_stats.championship = team_championship.championship) inner join "institute" on "institute"."id" = "team"."inst_id" where ("team"."hidden" = false and not exists (select "penalized_team_round"."id" from "team_round" "penalized_team_round" inner join "team_round_penalization" on "team_round_penalization"."team_round_id" = "penalized_team_round"."id" inner join "penalization" on "penalization"."id" = "team_round_penalization"."penalization_id" where ("penalized_team_round"."team_id" = "team"."id" and "penalization"."level" = 'red' and "penalization"."sent_at" is not null and ("penalization"."appeal_approved" is null or "penalization"."appeal_approved" = false)))) group by "team"."id", "team_championship"."championship", "team"."edition_id", "institute"."region");--> statement-breakpoint
CREATE MATERIALIZED VIEW "public"."v05a_edition_stats" AS (select "team"."edition_id", count(distinct "team"."id") as "total_teams", ROUND(COALESCE(sum("total_scores"), 0)::numeric, 2)::float8 as "total_scores", ROUND(COALESCE(max("total_scores"), 0)::numeric, 2)::float8 as "highest_score" from "v04a_team_stats" inner join "team" on ("team"."id" = "v04a_team_stats"."id" and "team"."hidden" = false) inner join "edition" on ("edition"."id" = "team"."edition_id" and "edition"."public" = true) where v04a_team_stats.championship = 'regolari' group by "team"."edition_id");--> statement-breakpoint
CREATE MATERIALIZED VIEW "public"."v06a_edition_stats2" AS (select "round"."edition_id", count(distinct "team"."inst_id") as "total_institutes", count(distinct "task"."id") as "total_tasks" from "v02b_team_round_stats" inner join "team_round" on "team_round"."id" = "v02b_team_round_stats"."id" inner join "team" on ("team"."id" = "team_round"."team_id" and "team"."hidden" = false) inner join "task" on "task"."round_id" = "team_round"."round_id" inner join "round" on ("round"."id" = "team_round"."round_id" and "round"."public" = true) inner join "edition" on ("edition"."id" = "round"."edition_id" and "edition"."public" = true) where v02b_team_round_stats.championship = 'regolari' group by "round"."edition_id");--> statement-breakpoint
CREATE MATERIALIZED VIEW "public"."v07a_institute_stats" AS (select "team"."inst_id", count(distinct "team"."edition_id") as "total_editions", count(distinct "team"."id") as "total_teams", ROUND(COALESCE(sum(v02b_team_round_stats.total_scores), 0)::numeric, 2)::float8 as "total_scores", JSON_BUILD_OBJECT(
        0, COUNT(*) FILTER (WHERE v02b_team_round_stats.medal = 0),
        1, COUNT(*) FILTER (WHERE v02b_team_round_stats.medal = 1),
        2, COUNT(*) FILTER (WHERE v02b_team_round_stats.medal = 2),
        3, COUNT(*) FILTER (WHERE v02b_team_round_stats.medal = 3)
      ) as "total_medals", ROUND(COALESCE(min(v04a_team_stats.rank_tot), 0)::numeric, 2)::float8 as "best_edition_rank", ROUND(COALESCE(min(v02b_team_round_stats.rank_tot), 0)::numeric, 2)::float8 as "best_round_rank" from "v02b_team_round_stats" inner join "team_round" on "team_round"."id" = "v02b_team_round_stats"."id" inner join "team" on ("team"."id" = "team_round"."team_id" and "team"."hidden" = false) inner join "v04a_team_stats" on "v04a_team_stats"."id" = "team"."id" inner join "round" on ("round"."id" = "team_round"."round_id" and "round"."public" = true) inner join "edition" on ("edition"."id" = "round"."edition_id" and "edition"."public" = true) where (v02b_team_round_stats.championship = 'regolari' and v04a_team_stats.championship = 'regolari') group by "team"."inst_id");--> statement-breakpoint
CREATE MATERIALIZED VIEW "public"."v08a_region_stats" AS (select "institute"."region", count(distinct "edition"."id") as "total_editions", count(distinct "institute"."id") as "total_institutes", count(distinct "team"."id") as "total_teams", ROUND(COALESCE(sum(v02b_team_round_stats.total_scores), 0)::numeric, 2)::float8 as "total_scores", JSON_BUILD_OBJECT(
        0, COUNT(*) FILTER (WHERE "medal" = 0),
        1, COUNT(*) FILTER (WHERE "medal" = 1),
        2, COUNT(*) FILTER (WHERE "medal" = 2),
        3, COUNT(*) FILTER (WHERE "medal" = 3)
      ) as "total_medals", ROUND(COALESCE(min(v04a_team_stats.rank_tot), 0)::numeric, 2)::float8 as "best_edition_rank", ROUND(COALESCE(min(v02b_team_round_stats.rank_tot), 0)::numeric, 2)::float8 as "best_round_rank" from "v02b_team_round_stats" inner join "team_round" on "team_round"."id" = "v02b_team_round_stats"."id" inner join "team" on ("team"."id" = "team_round"."team_id" and "team"."hidden" = false) inner join "v04a_team_stats" on "v04a_team_stats"."id" = "team"."id" inner join "round" on ("round"."id" = "team_round"."round_id" and "round"."public" = true) inner join "edition" on ("edition"."id" = "round"."edition_id" and "edition"."public" = true) inner join "institute" on "institute"."id" = "team"."inst_id" where (v02b_team_round_stats.championship = 'regolari' and v04a_team_stats.championship = 'regolari') group by "institute"."region");